{
  "items": [
    {
      "title": "German Federal Statistical Office (Destatis) – GENESIS-Online Education Statistics",
      "url_or_doi": "https://www.destatis.de/EN/Service/OpenData/api-webservice.html",
      "justification": "Official German government statistical database containing historical education data, including school enrollment, student populations, educational institutions, teachers, university students, and graduates. Provides annual statistics covering the 2010–2019 period. Particularly useful for analyzing trends in Germany's education system at national and regional levels. Data can be accessed through customizable tables and an API."
    },
    {
      "title": "Eurostat – Education and Training Database",
      "url_or_doi": "https://ec.europa.eu/eurostat/web/education-and-training/information-data",
      "justification": "Comprehensive European statistical database covering education in Germany throughout the 2010s. Includes student enrollment, educational attainment, graduation rates, participation in lifelong learning, vocational education, and education expenditure. Offers annual observations and demographic breakdowns by age, gender, and region. Particularly valuable for comparing Germany with other European countries."
    },
    {
      "title": "National Educational Panel Study (NEPS) – Germany",
      "url_or_doi": "https://www.lifbi.de/en-us/Start/Data-Services/Data-and-Documentation/SUF-Overview",
      "justification": "Major German longitudinal education study tracking educational pathways and competency development across different stages of life. Includes data collected throughout the 2010s from children, school pupils, university students, and adults. Provides detailed individual-level information about educational achievement, socioeconomic backgrounds, transitions between educational institutions, and learning outcomes. Scientific Use Files are available for research, subject to data-access requirements."
    },
    {
      "title": "NEPS Starting Cohort 3 – Grade 5 Students in Germany",
      "url_or_doi": "https://www.lifbi.de/en-us/Start/Data-Services/Data-and-Documentation/SUF-Overview",
      "justification": "Longitudinal dataset following German students who entered fifth grade during the 2010/2011 school year. Covers educational development, academic competencies, family backgrounds, school transitions, and educational outcomes throughout the 2010s. Particularly useful for investigating educational inequality, academic achievement, and student progression through Germany's secondary education system."
    },
    {
      "title": "NEPS Starting Cohort 4 – Grade 9 Students and Vocational Training",
      "url_or_doi": "https://www.lifbi.de/en-us/Start/Data-Services/Data-and-Documentation/SUF-Overview",
      "justification": "Longitudinal dataset following students attending ninth grade in Germany during the 2010/2011 school year. Includes information on secondary education, vocational training, academic competencies, educational aspirations, and transitions into employment or higher education. Covers multiple years during the 2010s and supports research into Germany's school-to-work transition and vocational education system."
    },
    {
      "title": "NEPS Starting Cohort 5 – First-Year University Students in Germany",
      "url_or_doi": "https://doi.org/10.5157/NEPS:SC5:19.0.0",
      "justification": "Longitudinal dataset beginning with approximately 17,900 students entering German higher education institutions in 2010/2011. Tracks university experiences, academic performance, educational decisions, degree completion, and transitions into employment. Particularly valuable for examining higher education participation, student mobility, university dropout, and educational inequality during the 2010s."
    },
    {
      "title": "NEPS Starting Cohort 2 – Kindergarten and Primary Education",
      "url_or_doi": "https://www.neps-data.de/Data-Center/Data-and-Documentation/SC2-Kindergarten/Data-and-Citation",
      "justification": "German longitudinal dataset beginning with kindergarten children in 2010 and following their educational development through subsequent school years. Includes early childhood learning, language development, cognitive competencies, family characteristics, and transitions into primary education. Useful for studying early educational inequalities and childhood education outcomes in Germany during the 2010s."
    },
    {
      "title": "NEPS Starting Cohort 6 – Adult Education and Lifelong Learning",
      "url_or_doi": "https://fdz.iab.de/en/pd_hd/national-educational-panel-study-neps-starting-cohort-6-sc6-survey-data-linked-to-administrative-data-of-the-iab-neps-sc6-adiab-version-7518-v1/",
      "justification": "Research dataset combining longitudinal survey information about adult educational trajectories with German administrative employment records. Includes observations from the 2010s on educational qualifications, vocational training, lifelong learning, professional development, and labor market outcomes. Particularly useful for analyzing relationships between education, employment, and earnings in Germany. Access to detailed microdata is restricted."
    },
    {
      "title": "Eurostat – Participation Rate in Education and Training by Educational Attainment Level",
      "url_or_doi": "https://ec.europa.eu/eurostat/databrowser/product/page/TRNG_LFSE_03",
      "justification": "Eurostat dataset measuring participation in education and training during the four weeks preceding the survey, categorized by educational attainment level. Contains historical observations for Germany covering the 2010s. Useful for studying adult learning, continuing education, differences between qualification groups, and participation trends over time. Allows comparisons with other European countries."
    },
    {
      "title": "OECD – Education at a Glance Historical Education Indicators",
      "url_or_doi": "https://www.oecd.org/en/publications/education-at-a-glance_19991487.html",
      "justification": "Annual OECD statistical publication series containing internationally comparable education indicators for Germany, including editions published throughout 2010–2019. Covers educational attainment, enrollment, graduation, education expenditure, teacher characteristics, and transitions into employment. Particularly valuable for studying changes in Germany's education system during the decade and comparing outcomes internationally. The linked page provides access to historical editions and their associated statistical tables."
    },
    {
      "title": "OECD Education GPS – Germany Country Education Data",
      "url_or_doi": "https://gpseducation.oecd.org/CountryProfile?primaryCountry=DEU",
      "justification": "OECD country-specific education data portal covering Germany's educational system, student outcomes, educational attainment, and education policy indicators. Includes historical indicators relevant to the 2010s, drawing on international education statistics and assessments. Useful for examining Germany's performance relative to other OECD countries, particularly in educational achievement, equity, and investment."
    },
    {
      "title": "Eurostat – Historical Education Administrative Data (ISCED 1997)",
      "url_or_doi": "https://ec.europa.eu/eurostat/web/education-and-training/information-data",
      "justification": "Historical education statistics compiled using the ISCED 1997 classification, covering Germany and other European countries. Provides non-financial education data through 2012 and education finance statistics through 2011. Particularly relevant for research examining the beginning of the 2010s, including enrollment patterns, educational levels, and changes in education systems. Complements newer Eurostat datasets based on ISCED 2011 classifications."
    }
  ]
}
